import React, { useState } from 'react';
import axios from 'axios';

const PassportMode = ({ currentUser, setActiveTab }) => {
    const [city, setCity] = useState('');
    const [country, setCountry] = useState('Kenya');
    const [hours, setHours] = useState(6);
    const [isActive, setIsActive] = useState(false);
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState('');

    const myPhone = currentUser?.phone || '0721143189';
    const API_BASE = 'http://localhost:5000/api/user';

    const handleActivate = async () => {
        setLoading(true);
        setMessage('');
        try {
            // Simulated lat/long lookup based on city (In production, use Google Geocoding API)
            const mockLat = -1.2921 + (Math.random() * 2);
            const mockLng = 36.8219 + (Math.random() * 2);

            await axios.post(`${API_BASE}/${myPhone}/passport`, {
                city: city,
                country: country,
                latitude: mockLat,
                longitude: mockLng,
                duration_hours: hours
            });
            setIsActive(true);
            setMessage(`Passport activated successfully for ${city}! You will appear there for ${hours} hours.`);
        } catch (err) {
            setMessage("Failed to activate Passport Mode.");
        } finally {
            setLoading(false);
        }
    };

    const handleDeactivate = async () => {
        setLoading(true);
        setMessage('');
        try {
            // Re-post physical location or call a deactivate endpoint
            setIsActive(false);
            setCity('');
            setMessage("Passport Mode deactivated. You are now visible at your physical location.");
        } catch (err) {
            setMessage("Failed to deactivate.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div style={{ padding: '30px', maxWidth: '800px', margin: '0 auto' }}>
            <div style={{ textAlign: 'center', marginBottom: '40px' }}>
                <h1 style={{ fontSize: '2.5rem', color: '#1f2937', margin: '0 0 10px 0' }}>🌍 Passport Mode</h1>
                <p style={{ color: '#6b7280', fontSize: '1.2rem', margin: 0 }}>Travel anywhere in the world and meet people globally.</p>
            </div>

            <div style={{ backgroundColor: 'white', padding: '40px', borderRadius: '16px', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)' }}>
                {message && (
                    <div style={{ padding: '15px', borderRadius: '8px', marginBottom: '20px', backgroundColor: isActive ? '#d1fae5' : '#f3f4f6', color: isActive ? '#065f46' : '#1f2937', fontWeight: 'bold', textAlign: 'center' }}>
                        {message}
                    </div>
                )}

                <div style={{ marginBottom: '20px' }}>
                    <label style={{ display: 'block', fontWeight: 'bold', marginBottom: '8px', color: '#374151' }}>🏙️ Search City</label>
                    <input 
                        type="text" 
                        value={city}
                        onChange={(e) => setCity(e.target.value)}
                        placeholder="e.g., Mombasa, Paris, New York"
                        disabled={isActive || loading}
                        style={{ width: '100%', padding: '15px', borderRadius: '12px', border: '2px solid #e5e7eb', fontSize: '1.1rem', boxSizing: 'border-box', backgroundColor: '#f9fafb', transition: 'border-color 0.2s' }}
                    />
                </div>

                <div style={{ marginBottom: '30px' }}>
                    <label style={{ display: 'block', fontWeight: 'bold', marginBottom: '8px', color: '#374151' }}>⏰ Set Duration (Hours)</label>
                    <select 
                        value={hours}
                        onChange={(e) => setHours(Number(e.target.value))}
                        disabled={isActive || loading}
                        style={{ width: '100%', padding: '15px', borderRadius: '12px', border: '2px solid #e5e7eb', fontSize: '1.1rem', backgroundColor: '#f9fafb', boxSizing: 'border-box', cursor: 'pointer' }}
                    >
                        <option value={1}>1 Hour</option>
                        <option value={3}>3 Hours</option>
                        <option value={6}>6 Hours</option>
                        <option value={12}>12 Hours</option>
                        <option value={24}>24 Hours</option>
                    </select>
                </div>

                <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
                    {!isActive ? (
                        <>
                            <button 
                                onClick={handleActivate}
                                disabled={loading || !city}
                                style={{ 
                                    flex: '1 1 45%', 
                                    padding: '16px', 
                                    borderRadius: '12px', 
                                    border: 'none', 
                                    fontSize: '1.1rem', 
                                    fontWeight: 'bold', 
                                    cursor: (loading || !city) ? 'not-allowed' : 'pointer',
                                    color: 'white',
                                    background: (loading || !city) ? '#9ca3af' : 'linear-gradient(135deg, #8b5cf6 0%, #6d28d9 100%)',
                                    boxShadow: '0 4px 6px rgba(109, 40, 217, 0.2)',
                                    transition: 'all 0.2s'
                                }}
                            >
                                ✈️ Activate Passport
                            </button>
                            <button 
                                onClick={() => { setCity(''); handleDeactivate(); }}
                                disabled={loading}
                                style={{ 
                                    flex: '1 1 45%', 
                                    padding: '16px', 
                                    borderRadius: '12px', 
                                    border: '2px solid #e5e7eb', 
                                    fontSize: '1.1rem', 
                                    fontWeight: 'bold', 
                                    cursor: loading ? 'not-allowed' : 'pointer',
                                    color: '#4b5563',
                                    backgroundColor: 'white',
                                    transition: 'all 0.2s'
                                }}
                            >
                                📍 Use Current Location
                            </button>
                        </>
                    ) : (
                        <>
                            <button 
                                onClick={() => setActiveTab && setActiveTab('discover')}
                                style={{ 
                                    flex: '1 1 45%', 
                                    padding: '16px', 
                                    borderRadius: '12px', 
                                    border: 'none', 
                                    fontSize: '1.1rem', 
                                    fontWeight: 'bold', 
                                    cursor: 'pointer',
                                    color: 'white',
                                    background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)',
                                    boxShadow: '0 4px 6px rgba(5, 150, 105, 0.2)'
                                }}
                            >
                                🔄 Explore Here
                            </button>
                            <button 
                                onClick={handleDeactivate}
                                disabled={loading}
                                style={{ 
                                    flex: '1 1 45%', 
                                    padding: '16px', 
                                    borderRadius: '12px', 
                                    border: 'none', 
                                    fontSize: '1.1rem', 
                                    fontWeight: 'bold', 
                                    cursor: loading ? 'not-allowed' : 'pointer',
                                    color: 'white',
                                    background: '#ef4444',
                                    boxShadow: '0 4px 6px rgba(239, 68, 68, 0.2)'
                                }}
                            >
                                🚫 Deactivate
                            </button>
                        </>
                    )}
                </div>
            </div>
        </div>
    );
};

export default PassportMode;
